INSERT INTO qbi_usmle_refs_s12b9_20261121_stage (id, step, url, quote, "references") VALUES
  ('b1x329fa184ac810b95976a2c11', 'usmle-step-1', 'https://www.ncbi.nlm.nih.gov/books/NBK553135/', 'This regurgitant flow produces a characteristic holosystolic murmur best heard at the cardiac apex with radiation toward the left axilla and, when progressive or severe, results in chronic volume overload of both the left atrium and left ventricle', '[{"label": "StatPearls. Mitral Regurgitation. This regurgitant flow produces a characteristic holosystolic murmur best heard at the cardiac apex with radiation toward the left axilla and, when progressive or severe, results in chronic volume overload of both the left atrium and left ventricle", "url": "https://www.ncbi.nlm.nih.gov/books/NBK553135/"}]'::jsonb),
  ('b1xe07ca0323d3bce455a44a7e7', 'usmle-step-1', 'https://www.ncbi.nlm.nih.gov/books/NBK562171/', 'Crigler-Najjar syndrome is characterized by the absence or decreased activity of UDP-glucuronosyltransferase (UGT), an enzyme required for glucuronidation of unconjugated bilirubin in the liver.', '[{"label": "StatPearls. Crigler-Najjar Syndrome. Crigler-Najjar syndrome is characterized by the absence or decreased activity of UDP-glucuronosyltransferase (UGT), an enzyme required for glucuronidation of unconjugated bilirubin in the liver.", "url": "https://www.ncbi.nlm.nih.gov/books/NBK562171/"}]'::jsonb),
  ('b7x0b161a942f7f785c788f8715', 'usmle-step-1', 'https://www.ncbi.nlm.nih.gov/books/NBK553135/', 'The disorder is characterized by the retrograde flow of blood from the left ventricle into the left atrium during systole due to incomplete coaptation of the mitral valve leaflets.', '[{"label": "StatPearls. Mitral Regurgitation. The disorder is characterized by the retrograde flow of blood from the left ventricle into the left atrium during systole due to incomplete coaptation of the mitral valve leaflets.", "url": "https://www.ncbi.nlm.nih.gov/books/NBK553135/"}]'::jsonb),
